-- Optional sample data: a published chaptered lesson about mangroves. Not a migration; run it once by hand
-- in the SQL Editor of the project you want it in. It does nothing if a lesson with this slug already exists.
-- The same text is in sample-mangrove-lesson.md, for Admin > Tides > New lesson > import instead of SQL.
-- Add a cover image, images in the text and a quiz afterwards from Admin > Tides > this lesson.
insert into public.tides(author_id,title,slug,summary,body,status,paged,category_id)
select
 (select id from public.profiles where role='admin' order by created_at limit 1),
 'Mangroves: Reading a Healthy Stand',
 'mangroves-reading-a-healthy-stand',
 'How to tell a healthy mangrove stand from a stressed one, and how to record what you see.',
 E'Mangroves protect the coast, shelter young fish and store carbon in their mud. This lesson shows you how to tell a healthy mangrove stand from a stressed one, and how to record what you see as a useful trace.\n\n## Why mangroves matter\nMangroves are trees and shrubs that grow where the sea meets the land, in mud that is flooded by the tide twice a day.\n\n- Their roots slow down waves and hold mud in place, which protects the shore during storms.\n- The shaded water between the roots is a nursery for young fish, crabs and shrimp.\n- Their waterlogged mud locks away carbon for a very long time.\n\n## Reading the roots\nThe roots tell you which kind of mangrove you are looking at.\n\n1. **Prop roots.** Arching roots that hold the trunk above the water, like the legs of a stool.\n2. **Pencil roots.** Thin roots that poke straight up out of the mud around the tree. They help the roots breathe at low tide.\n3. **Knee roots.** Roots that loop up out of the mud and back down again.\n\nNote which root type is most common at your spot. It is a quick way to describe the stand without knowing every species name.\n\n## Signs of a healthy stand\nLook for these when you visit at low tide:\n\n- Green leaves on most trees, with new shoots at the tips.\n- Seedlings or young plants growing between the older trees.\n- Crab holes and snail trails in the mud, which show animals living there.\n\n## Signs of stress\nThese are worth recording, even if you are not sure what caused them:\n\n1. **Cut stumps** or missing trees in a clear line.\n2. **Trash** caught in the roots, especially plastic bags and fishing nets.\n3. **Yellow or bare branches** on many trees at once.\n4. **Mud covered by sand** or by soil washed down from land.\n\n### Stay safe\nMangrove mud can be deep and soft. Stay on firm ground or a boardwalk, go with someone, and check the tide time before you walk out.\n\n## Recording a trace\nOpen **Submit a trace** and choose the **Mangroves** topic. In the description, say which root type you saw most, and list the healthy signs and the stress signs you noticed.\n\nAdd one wide photo of the stand and one close photo of a stress sign, with something for scale. Add your location and the time of your visit, then save a draft or submit for review.\n\n## Key takeaways\n- Roots tell you what kind of mangrove you are looking at.\n- Seedlings, green leaves and crab holes mean a living stand.\n- Cut stumps, trash and bare branches are worth a trace, even when the cause is unclear.',
 'published',
 true,
 coalesce((select id from public.categories where name='Mangroves' and is_active limit 1),
          (select id from public.categories where is_active order by created_at limit 1))
where exists (select 1 from public.profiles where role='admin')
  and not exists (select 1 from public.tides where slug='mangroves-reading-a-healthy-stand');
